		t.Fatalf("batched insert after migration: %v", err)
	}
	// Reopening must be a no-op migration (indexes already present).
	if err := db.migrateReleaseBatchIndexes(); err != nil {
		t.Fatalf("idempotent migration: %v", err)
	}
}

