		where = append(where, `r.gate_status = ?`)
		args = append(args, filter.GateStatus)
	}
	if filter.From != "" {
		where = append(where, `r.recorded_at >= ?`)
		args = append(args, filter.From)
	}
	if filter.To != "" {
