	pageSizes := []int{2, 2, 2}
	for page, size := range pageSizes {
		target := "/api/v1/change-entries?limit=" + itoa(size)
		if cursor != "" {
			target += "&cursor=" + cursor
		}
		recorder := doRequest(t, router, http.MethodGet, target, "")
