		if len(changes) != size {
			t.Fatalf("page %d size = %d, want %d", page, len(changes), size)
		}
		collected = append(collected, changes...)
		nextCursor, _ := body["next_cursor"].(string)
		if page == len(pageSizes)-1 {
			if nextCursor != "" {
				t.Fatalf("last page next_cursor = %q, want empty", nextCursor)
			}
